// WatchbillRequestAddSections contributes this kind's tagged sections to the OPEN
// entity on dml — the BuildEntities body without the entity frame.
// The caller owns BeginEntity / plain setters / CommitEntity.
func WatchbillRequestAddSections[
	SymbolAttr WatchbillRequestSymbolAttrI,
	SymbolSec WatchbillRequestSymbolSecI[SymbolAttr, Ent],
	StringArrayAttr WatchbillRequestStringArrayAttrI,
	StringArraySec WatchbillRequestStringArraySecI[StringArrayAttr, Ent],
	TextArrayAttr WatchbillRequestTextArrayAttrI,
	TextArraySec WatchbillRequestTextArraySecI[TextArrayAttr, Ent],
	U32ArrayAttr WatchbillRequestU32ArrayAttrI,
	U32ArraySec WatchbillRequestU32ArraySecI[U32ArrayAttr, Ent],
	U64ArrayAttr WatchbillRequestU64ArrayAttrI,
	U64ArraySec WatchbillRequestU64ArraySecI[U64ArrayAttr, Ent],
	BlobArrayAttr WatchbillRequestBlobArrayAttrI,
	BlobArraySec WatchbillRequestBlobArraySecI[BlobArrayAttr, Ent],
	I64ArrayAttr WatchbillRequestI64ArrayAttrI,
	I64ArraySec WatchbillRequestI64ArraySecI[I64ArrayAttr, Ent],
	SymbolArrayAttr WatchbillRequestSymbolArrayAttrI,
	SymbolArraySec WatchbillRequestSymbolArraySecI[SymbolArrayAttr, Ent],
	Ent any,
	DML WatchbillRequestEntityI[
		SymbolAttr, SymbolSec,
		StringArrayAttr, StringArraySec,
		TextArrayAttr, TextArraySec,
		U32ArrayAttr, U32ArraySec,
		U64ArrayAttr, U64ArraySec,
		BlobArrayAttr, BlobArraySec,
		I64ArrayAttr, I64ArraySec,
		SymbolArrayAttr, SymbolArraySec,
		Ent,
	],
](dml DML, row WatchbillRequest) (err error) {
	// --- symbol. ---
	symbolSec := dml.GetSectionSymbol()
	err = WatchbillRequestEmitSectionSymbol(symbolSec, row)
	if err != nil {
		return
	}
	symbolSec.EndSection()
	// --- stringArray. ---
	stringArraySec := dml.GetSectionStringArray()
	err = WatchbillRequestEmitSectionStringArray(stringArraySec, row)
	if err != nil {
		return
	}
	stringArraySec.EndSection()
	// --- textArray. ---
	textArraySec := dml.GetSectionTextArray()
	err = WatchbillRequestEmitSectionTextArray(textArraySec, row)
	if err != nil {
		return
	}
	textArraySec.EndSection()
	// --- u32Array. ---
	u32ArraySec := dml.GetSectionU32Array()
	err = WatchbillRequestEmitSectionU32Array(u32ArraySec, row)
	if err != nil {
		return
	}
	u32ArraySec.EndSection()
	// --- u64Array. ---
	u64ArraySec := dml.GetSectionU64Array()
	err = WatchbillRequestEmitSectionU64Array(u64ArraySec, row)
	if err != nil {
		return
	}
	u64ArraySec.EndSection()
	// --- blobArray. ---
	blobArraySec := dml.GetSectionBlobArray()
	err = WatchbillRequestEmitSectionBlobArray(blobArraySec, row)
	if err != nil {
		return
	}
	blobArraySec.EndSection()
	// --- i64Array. ---
	i64ArraySec := dml.GetSectionI64Array()
	err = WatchbillRequestEmitSectionI64Array(i64ArraySec, row)
	if err != nil {
		return
	}
	i64ArraySec.EndSection()
	// --- symbolArray. ---
	symbolArraySec := dml.GetSectionSymbolArray()
	err = WatchbillRequestEmitSectionSymbolArray(symbolArraySec, row)
	if err != nil {
		return
	}
	symbolArraySec.EndSection()
	return
}

