// --- Sparse-CBOR write (ADR-0042 driver path). ---

// Marshal writes the SoA buffer to w as the sparse-CBOR wire
// format produced through factsschema/dml_cbor. Thin wrapper
// around WatchbillRequestBuildEntities — the per-row chain lives there and
// works against any leeway-DML class that structurally satisfies
// WatchbillRequestEntityI.
func (c *WatchbillRequestColumns) Marshal(w io.Writer) (err error) {
	ent := watchbillRequestPool.Get().(*cbdml.InEntityFacts)
	defer watchbillRequestPool.Put(ent)
	ent.SetActiveSections(WatchbillRequestActiveSections)
	ent.Builder().SetActiveFields(WatchbillRequestActiveFields())
	err = WatchbillRequestBuildEntities(ent, c)
	if err != nil {
		return
	}
	var recs []*arrowrowcbor.Record
	recs, err = ent.TransferRecords(nil)
	if err != nil {
		err = eh.Errorf("watchbillrequest: transfer records: %w", err)
		return
	}
	rb := arrowrowcbor.JoinRecords(recs)
	_, err = w.Write(rb)
	if err != nil {
		err = eh.Errorf("watchbillrequest: marshal write: %w", err)
	}
	return
}

